/* src/pages/tabs/TasksYamlTab.tsx */
import React, { useState, useEffect } from 'react';
import ChatInterface, { ChatMessage } from '../../components/documents/ChatInterface';
import AgentTaskSpecHistoryModal from '../../components/agent-task/AgentTaskSpecHistoryModal';
import TasksYamlHistoryModal from '../../components/yaml/TasksYamlHistoryModal';
import ReviewSuggestionsModal from '../../components/agent-task/ReviewSuggestionsModal';
import DocumentActionsCard from '../../components/documents/DocumentActionsCard';
import YamlViewerModal from '../../components/yaml/YamlViewerModal';
import MarkdownEditorModal from '../../components/documents/MarkdownEditorModal';
import DiffViewerModal from '../../components/documents/DiffViewerModal';
import StagePageLayout from '../../components/stage/StagePageLayout';
import { estruturarPassos } from '../../services/tasksYamlService';
import { toast } from 'react-toastify';
import '../DocumentsPage.css'; // USA O MESMO CSS
import * as tasksYamlService from '../../services/tasksYamlService';

interface TasksYamlTabProps {
  projectId?: string;
  tabSwitcher?: React.ReactNode;
}

const TasksYamlTab: React.FC<TasksYamlTabProps> = ({ projectId, tabSwitcher }) => {

  // Specification selection states
  const [isSpecModalOpen, setIsSpecModalOpen] = useState(false);
  const [selectedSpecSessionId, setSelectedSpecSessionId] = useState<string>('');
  const [selectedSpecVersion, setSelectedSpecVersion] = useState<number>(1);
  const [selectedSpecName, setSelectedSpecName] = useState<string>('');

  // Task history modal
  const [isHistoryModalOpen, setIsHistoryModalOpen] = useState(false);

  // Generation states
  const [isGenerating, setIsGenerating] = useState(false);
  const [currentSessionId, setCurrentSessionId] = useState<string | undefined>(undefined);

  // Chat states
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([]);
  const [isChatProcessing, setIsChatProcessing] = useState(false);

  // Configuration states
  const [customInstructions, setCustomInstructions] = useState('');
  const [detailLevel, setDetailLevel] = useState<'concise' | 'balanced' | 'detailed'>('balanced');
  const [selectedFrameworks, setSelectedFrameworks] = useState<string[]>(['CrewAI']);

  // Results states
  const [generatedYaml, setGeneratedYaml] = useState<string>('');
  const [currentLoadedVersion, setCurrentLoadedVersion] = useState<number | null>(null);
  const [totalTasks, setTotalTasks] = useState<number>(0);

  // Modal states
  const [isViewerOpen, setIsViewerOpen] = useState(false);
  const [isEditorOpen, setIsEditorOpen] = useState(false);
  const [yamlFilename, setYamlFilename] = useState<string>('tasks.yaml');

  // Diff states (seguindo padrão do SpecificationPage)
  const [showDiff, setShowDiff] = useState(false);
  const [oldYaml, setOldYaml] = useState<string>('');
  const [isDiffModalOpen, setIsDiffModalOpen] = useState(false);

  // Review modal states
  const [isReviewModalOpen, setIsReviewModalOpen] = useState(false);
  const [reviewSuggestions, setReviewSuggestions] = useState<string>('');
  const [isReviewing, setIsReviewing] = useState(false);
  const [isApplyingSuggestions, setIsApplyingSuggestions] = useState(false);

  // useEffect para detectar diffs automaticamente (padrão SpecificationPage)
  useEffect(() => {
    if (chatMessages.length === 0) return;

    const lastMessage = chatMessages[chatMessages.length - 1];

    // Backend envia has_diff=true quando há alteração
    if (lastMessage?.data?.has_diff &&
        lastMessage.data.old_yaml &&
        lastMessage.data.new_yaml) {
      console.log('📊 Diff detectado na última mensagem');

      // Armazena versões antiga e nova
      setOldYaml(lastMessage.data.old_yaml);
      setGeneratedYaml(lastMessage.data.new_yaml);
      setShowDiff(true);
      setIsDiffModalOpen(true);

      toast.success('tasks.yaml refinado! Clique em "Ver Diferenças" para comparar as alterações.');
    }
  }, [chatMessages]);

  // Handler for specification selection (from SpecificationHistoryModal)
  const handleSpecSessionSelect = (sessionId: string, sessionName: string) => {
    setSelectedSpecSessionId(sessionId);
    setSelectedSpecName(sessionName);
  };

  const handleSpecVersionSelect = (sessionId: string, version: number) => {
    setSelectedSpecSessionId(sessionId);
    setSelectedSpecVersion(version);
    toast.success(`Documento selecionado: v${version}`);
  };

  // Handler for loading tasks.yaml session from history
  const handleHistorySessionSelect = async (sessionId: string, sessionName: string) => {
    try {
      const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:8000/api';
      const token = localStorage.getItem('accessToken') || localStorage.getItem('token');

      const response = await fetch(`${API_BASE_URL}/tasks-yaml/${sessionId}`, {
        headers: {
          'Authorization': token ? `Bearer ${token}` : '',
          'Content-Type': 'application/json',
        }
      });

      if (!response.ok) {
        throw new Error('Falha ao carregar sessão');
      }

      const session = await response.json();

      // A resposta traz `id`, não `session_id`: carregar do histórico deixava a sessão vazia e
      // as ações da etapa (refinar, aprovar, estruturar) ficavam desabilitadas.
      setCurrentSessionId(session.session_id || session.id || sessionId);
      setGeneratedYaml(session.tasks_yaml_content || '');
      setCurrentLoadedVersion(null); // Reset version when loading session
      setTotalTasks(session.total_tasks || 0);

      toast.success(`tasks.yaml carregado: ${sessionName}`);
    } catch (error: any) {
      console.error('Erro ao carregar sessão:', error);
      toast.error('Erro ao carregar tasks.yaml do histórico');
    }
  };

  // Handler for loading specific version from history (padrão SpecificationPage)
  const handleHistoryVersionSelect = async (sessionId: string, version: number) => {
    try {
      const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:8000/api';
      const token = localStorage.getItem('accessToken') || localStorage.getItem('token');

      // Buscar TODAS as versões da API
      const response = await fetch(`${API_BASE_URL}/tasks-yaml/${sessionId}/versions`, {
        headers: {
          'Authorization': token ? `Bearer ${token}` : '',
          'Content-Type': 'application/json',
        }
      });

      if (!response.ok) {
        throw new Error('Falha ao carregar versões');
      }

      // O serviço devolve { versions: [...], total: N } — a página tratava como se fosse a lista
      // direta e o .find estourava: clicar numa versão do histórico SEMPRE dava "Erro ao carregar
      // versão" (achado em 13/09/2026 ao refinar o contrato pela interface). Aceita as duas formas.
      const payload = await response.json();
      const versions = Array.isArray(payload) ? payload : (payload?.versions || []);

      // Buscar a versão solicitada
      const versionData = versions.find((v: any) => v.version === version);

      if (!versionData || !versionData.tasks_yaml_content) {
        throw new Error('Versão não encontrada');
      }

      // Buscar a versão ANTERIOR (se existir) para diff
      let previousVersionYaml = '';
      if (version > 1) {
        const previousVersionData = versions.find((v: any) => v.version === version - 1);
        if (previousVersionData && previousVersionData.tasks_yaml_content) {
          previousVersionYaml = previousVersionData.tasks_yaml_content;
        }
      }

      // Atualizar estados
      setCurrentSessionId(sessionId);
      setGeneratedYaml(versionData.tasks_yaml_content);
      setCurrentLoadedVersion(version);
      setYamlFilename(`tasks_v${version}.yaml`);

      // Ativar diff se houver versão anterior
      if (previousVersionYaml) {
        setOldYaml(previousVersionYaml);
        setShowDiff(true);
        toast.success(`Versão ${version} carregada. Clique em "Ver Diferenças" para comparar com v${version - 1}.`);
      } else {
        // Limpar diff se for a versão 1
        setOldYaml('');
        setShowDiff(false);
        toast.success(`Versão ${version} carregada (versão inicial)`);
      }
    } catch (error: any) {
      console.error('Erro ao carregar versão:', error);
      toast.error('Erro ao carregar versão do histórico');
    }
  };

  // Handler for generation
  const startGeneration = async () => {
    if (!selectedSpecSessionId) {
      toast.error('Selecione um documento de especificação de agentes/tarefas primeiro');
      return;
    }

    setIsGenerating(true);
    setIsChatProcessing(true);

    try {
      // Mensagem inicial no chat
      const systemMsg: ChatMessage = {
        id: Date.now().toString(),
        sender: 'system',
        text: '🚀 Gerando tasks.yaml...',
        timestamp: new Date(),
        type: 'status'
      };
      setChatMessages([systemMsg]);

      // Chamar API para gerar tasks.yaml
      const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:8000/api';
      const token = localStorage.getItem('accessToken') || localStorage.getItem('token');

      const response = await fetch(`${API_BASE_URL}/tasks-yaml/`, {
        method: 'POST',
        headers: {
          'Authorization': token ? `Bearer ${token}` : '',
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          agent_task_spec_session_id: selectedSpecSessionId,
          agent_task_spec_version: selectedSpecVersion,
          custom_instructions: customInstructions || undefined,
          detail_level: detailLevel,
          selected_frameworks: selectedFrameworks
        })
      });

      if (!response.ok) {
        throw new Error('Falha ao gerar tasks.yaml');
      }

      const result = await response.json();
      setCurrentSessionId(result.session_id);

      // Polling para obter tasks.yaml gerado
      const pollInterval = setInterval(async () => {
        const statusRes = await fetch(`${API_BASE_URL}/tasks-yaml/${result.session_id}`, {
          headers: {
            'Authorization': token ? `Bearer ${token}` : '',
            'Content-Type': 'application/json'
          }
        });

        if (statusRes.ok) {
          const statusData = await statusRes.json();

          if (statusData.status === 'completed') {
            clearInterval(pollInterval);

            setGeneratedYaml(statusData.tasks_yaml_content || '');
            setTotalTasks(statusData.total_tasks || 0);

            const successMsg: ChatMessage = {
              id: (Date.now() + 1).toString(),
              sender: 'agent',
              text: `✅ tasks.yaml gerado com sucesso!\n\n📊 ${statusData.total_tasks} agentes configurados.`,
              timestamp: new Date(),
              type: 'result'
            };
            setChatMessages(prev => [...prev, successMsg]);

            setIsChatProcessing(false);
            toast.success('tasks.yaml gerado com sucesso');
          } else if (statusData.status === 'failed') {
            clearInterval(pollInterval);
            throw new Error('Geração falhou');
          }
        }
      }, 3000); // Poll a cada 3 segundos

    } catch (error: any) {
      console.error('Erro ao gerar tasks.yaml:', error);

      const errorMsg: ChatMessage = {
        id: (Date.now() + 2).toString(),
        sender: 'system',
        text: `❌ Erro: ${error.message || 'Falha ao gerar tasks.yaml'}`,
        timestamp: new Date(),
        type: 'status'
      };
      setChatMessages(prev => [...prev, errorMsg]);

      toast.error(error.message || 'Erro ao gerar tasks.yaml');
      setIsChatProcessing(false);
    } finally {
      setIsGenerating(false);
    }
  };

  // Handler for chat refinement
  const handleChatSend = async (message: string) => {
    if (!currentSessionId) {
      toast.error('Nenhuma sessão ativa');
      return;
    }

    setIsChatProcessing(true);

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      sender: 'user',
      text: message,
      timestamp: new Date()
    };
    setChatMessages(prev => [...prev, userMsg]);

    // Salvar YAML atual como oldYaml para comparação posterior
    const yamlBeforeRefinement = generatedYaml;

    try {
      // Chamar API para refinar tasks.yaml
      const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:8000/api';
      const token = localStorage.getItem('accessToken') || localStorage.getItem('token');

      const response = await fetch(`${API_BASE_URL}/tasks-yaml/${currentSessionId}/refine`, {
        method: 'POST',
        headers: {
          'Authorization': token ? `Bearer ${token}` : '',
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          message: message,
          action_type: 'refine'
        })
      });

      if (!response.ok) {
        throw new Error('Falha ao refinar tasks.yaml');
      }

      // Iniciar polling para aguardar refinamento
      const pollInterval = setInterval(async () => {
        const statusRes = await fetch(`${API_BASE_URL}/tasks-yaml/${currentSessionId}`, {
          headers: {
            'Authorization': token ? `Bearer ${token}` : '',
            'Content-Type': 'application/json'
          }
        });

        if (statusRes.ok) {
          const statusData = await statusRes.json();

          if (statusData.status === 'completed') {
            clearInterval(pollInterval);

            const refinedYaml = statusData.tasks_yaml_content || '';

            // Atualizar YAML refinado
            setGeneratedYaml(refinedYaml);
            setTotalTasks(statusData.total_tasks || 0);

            // Ativar diff (seguindo padrão SpecificationPage)
            setOldYaml(yamlBeforeRefinement);
            setShowDiff(true);

            // Incrementar versão
            const newVersion = (currentLoadedVersion || 1) + 1;
            setCurrentLoadedVersion(newVersion);
            setYamlFilename(`tasks_v${newVersion}.yaml`);

            // Mensagem da assistente no chat com has_diff
            const assistantMsg: ChatMessage = {
              id: (Date.now() + 1).toString(),
              sender: 'agent',
              text: `✅ Refinamento aplicado com sucesso!\n\nVersão ${newVersion} criada. Clique em "Ver Diferenças" para comparar as alterações.`,
              timestamp: new Date(),
              type: 'result',
              data: {
                has_diff: true,
                old_yaml: yamlBeforeRefinement,
                new_yaml: refinedYaml
              }
            };
            setChatMessages(prev => [...prev, assistantMsg]);

            setIsChatProcessing(false);
            toast.success(`Refinamento aplicado - v${newVersion} criada`);
          } else if (statusData.status === 'failed') {
            clearInterval(pollInterval);
            setIsChatProcessing(false);
            throw new Error('Refinamento falhou');
          }
        }
      }, 3000); // Poll a cada 3 segundos

    } catch (error: any) {
      console.error('Erro ao refinar:', error);

      const errorMsg: ChatMessage = {
        id: (Date.now() + 2).toString(),
        sender: 'system',
        text: `❌ Erro: ${error.message || 'Falha ao refinar'}`,
        timestamp: new Date(),
        type: 'status'
      };
      setChatMessages(prev => [...prev, errorMsg]);

      toast.error(error.message || 'Erro ao processar refinamento');
      setIsChatProcessing(false);
    }
  };

  // Handler for review
  const handleReview = async () => {
    if (!currentSessionId) {
      toast.error('Gere tasks.yaml primeiro');
      return;
    }

    setIsReviewing(true);
    try {
      console.log('🔍 Iniciando revisão do tasks.yaml...');
      const result = await tasksYamlService.reviewTasksYaml(currentSessionId);
      setReviewSuggestions(result.suggestions);
      setIsReviewModalOpen(true);

      // Add review message to chat
      const reviewMsg: ChatMessage = {
        id: result.review_message_id,
        sender: 'agent',
        text: result.suggestions,
        timestamp: new Date(),
        type: 'result'
      };
      setChatMessages(prev => [...prev, reviewMsg]);

      toast.success('Revisão concluída!');
    } catch (error: any) {
      console.error('Erro ao revisar tasks.yaml:', error);
      toast.error('Erro ao revisar tasks.yaml. Tente novamente.');
    } finally {
      setIsReviewing(false);
    }
  };

  // Handler for applying suggestions
  const handleApplySuggestions = async (additionalInstructions?: string) => {
    if (!currentSessionId) {
      toast.error('Nenhuma sessão ativa');
      return;
    }

    setIsApplyingSuggestions(true);

    // Salvar YAML antes do refinamento para diff
    const yamlBeforeRefinement = generatedYaml;

    try {
      // Build refinement message
      let message = "Aplique as seguintes sugestões de melhoria ao tasks.yaml:\n\n";
      message += reviewSuggestions;

      if (additionalInstructions) {
        message += `\n\n---\n\nINSTRUÇÕES COMPLEMENTARES:\n${additionalInstructions}`;
      }

      console.log('✏️ Aplicando sugestões de revisão...');

      const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:8000/api';
      const token = localStorage.getItem('accessToken') || localStorage.getItem('token');

      // Chamar endpoint de refinamento
      const response = await fetch(`${API_BASE_URL}/tasks-yaml/${currentSessionId}/refine`, {
        method: 'POST',
        headers: {
          'Authorization': token ? `Bearer ${token}` : '',
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          message: message,
          action_type: 'refine'
        })
      });

      if (!response.ok) {
        throw new Error('Falha ao aplicar sugestões');
      }

      setIsReviewModalOpen(false);
      setIsChatProcessing(true);
      toast.success('Aplicando sugestões... Aguarde a atualização do tasks.yaml.');

      // Iniciar polling para aguardar refinamento
      const pollInterval = setInterval(async () => {
        const statusRes = await fetch(`${API_BASE_URL}/tasks-yaml/${currentSessionId}`, {
          headers: {
            'Authorization': token ? `Bearer ${token}` : '',
            'Content-Type': 'application/json'
          }
        });

        if (statusRes.ok) {
          const statusData = await statusRes.json();

          if (statusData.status === 'completed') {
            clearInterval(pollInterval);

            const refinedYaml = statusData.tasks_yaml_content || '';

            // Atualizar YAML refinado
            setGeneratedYaml(refinedYaml);
            setTotalTasks(statusData.total_tasks || 0);

            // Ativar diff
            setOldYaml(yamlBeforeRefinement);
            setShowDiff(true);

            // Incrementar versão
            const newVersion = (currentLoadedVersion || 1) + 1;
            setCurrentLoadedVersion(newVersion);
            setYamlFilename(`tasks_v${newVersion}.yaml`);

            // Mensagem da assistente no chat
            const assistantMsg: ChatMessage = {
              id: (Date.now() + 1).toString(),
              sender: 'agent',
              text: `✅ Sugestões aplicadas com sucesso!\n\nVersão ${newVersion} criada. Clique em "Ver Diferenças" para comparar as alterações.`,
              timestamp: new Date(),
              type: 'result',
              data: {
                has_diff: true,
                old_yaml: yamlBeforeRefinement,
                new_yaml: refinedYaml
              }
            };
            setChatMessages(prev => [...prev, assistantMsg]);

            setIsChatProcessing(false);
            setIsApplyingSuggestions(false);
            toast.success(`Sugestões aplicadas - v${newVersion} criada`);
          } else if (statusData.status === 'failed') {
            clearInterval(pollInterval);
            setIsChatProcessing(false);
            setIsApplyingSuggestions(false);
            toast.error('Refinamento falhou');
          }
        }
      }, 3000); // Poll a cada 3 segundos

    } catch (error: any) {
      console.error('Erro ao aplicar sugestões:', error);
      toast.error('Erro ao aplicar sugestões. Tente novamente.');
      setIsApplyingSuggestions(false);
      setIsChatProcessing(false);
    }
  };

  const handleDownloadMarkdown = () => {
    if (!generatedYaml) {
      toast.error('Nenhum tasks.yaml para baixar');
      return;
    }

    try {
      const blob = new Blob([generatedYaml], { type: 'text/yaml' });
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = yamlFilename;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      window.URL.revokeObjectURL(url);

      toast.success('tasks.yaml baixado com sucesso');
    } catch (error) {
      console.error('Erro ao baixar tasks.yaml:', error);
      toast.error('Erro ao baixar tasks.yaml');
    }
  };

  const handleSaveEdit = (newContent: string) => {
    setGeneratedYaml(newContent);
    toast.success('tasks.yaml editado localmente. Use "Download" para salvar.');
  };

  // ---- Botões de origem da sidebar: seleção do documento MD de agentes/tarefas ----
  const sourceButtons = (
    <button
      className={`btn-requirements-compact ${selectedSpecSessionId ? 'selected' : ''}`}
      onClick={() => setIsSpecModalOpen(true)}
      title="Selecionar Documento de Agentes/Tarefas Base"
    >
      📝 {selectedSpecSessionId ? 'Doc MD ✓' : 'Doc MD'}
    </button>
  );

  const sourceBanner = selectedSpecSessionId ? (
    <div style={{
      padding: '8px 12px',
      backgroundColor: '#d4edda',
      borderBottom: '1px solid #c3e6cb',
      fontSize: '12px'
    }}>
      <strong>📝 Base:</strong> {selectedSpecName} (v{selectedSpecVersion})
    </div>
  ) : (
    <div className="documents-compact-list">
      <div className="empty-sidebar">
        <p>Selecione um documento de especificação de agentes/tarefas</p>
        <button onClick={() => setIsSpecModalOpen(true)}>
          📝 Selecionar Documento MD
        </button>
      </div>
    </div>
  );

  // Abre automaticamente a sessão mais recente do projeto (padrão "auto — mais recente" das
  // outras etapas): sem isso as ações da etapa ficavam desabilitadas até o usuário achar a
  // sessão no histórico.
  useEffect(() => {
    if (!projectId || currentSessionId) return;
    (async () => {
      try {
        const r: any = await tasksYamlService.listTasksYamlSessions(projectId);
        const lista: any[] = Array.isArray(r) ? r : (r?.sessions || []);
        const ok = lista.filter((x) => x.status === 'completed' && x.id);
        if (ok.length) {
          ok.sort((a, b) => String(b.created_at || '').localeCompare(String(a.created_at || '')));
          await handleHistorySessionSelect(ok[0].id, ok[0].session_name || 'tasks.yaml');
        }
      } catch (e) { /* sem sessão anterior: a etapa começa vazia */ }
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [projectId]);

  // ---- ESTRUTURAR PASSOS (tradutor de regras) ----
  // Converte a prosa de cada tarefa em `steps:` com tipos fechados; cada expressão é validada
  // ANTES de gravar. O que não validar volta marcado como passo de agente para refinar.
  const [estruturando, setEstruturando] = useState(false);
  const [relatorioPassos, setRelatorioPassos] = useState<any[] | null>(null);
  const handleEstruturar = async () => {
    if (!currentSessionId) return;
    setEstruturando(true); setRelatorioPassos(null);
    try {
      const r = await estruturarPassos(currentSessionId);
      setRelatorioPassos(r.relatorio || []);
      const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:8000/api';
      const token = localStorage.getItem('accessToken') || localStorage.getItem('token') || '';
      const sess = await fetch(`${API_BASE_URL}/tasks-yaml/${currentSessionId}`, { headers: { Authorization: `Bearer ${token}` } });
      if (sess.ok) { const d = await sess.json(); if (d.tasks_yaml_content) setGeneratedYaml(d.tasks_yaml_content); }
    } catch (e: any) { setRelatorioPassos([{ tarefa: '—', situacao: 'erro', erro: String(e.message || e) }]); }
    setEstruturando(false);
  };

  const [restaurando, setRestaurando] = useState(false);
  const handleRestaurar = async () => {
    if (!currentSessionId || !currentLoadedVersion) return;
    setRestaurando(true);
    try {
      const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:8000/api';
      const token = localStorage.getItem('accessToken') || localStorage.getItem('token') || '';
      const r = await fetch(`${API_BASE_URL}/tasks-yaml/${currentSessionId}/restore/${currentLoadedVersion}`,
        { method: 'POST', headers: { Authorization: `Bearer ${token}` } });
      if (!r.ok) throw new Error((await r.json().catch(() => ({}))).detail || 'falhou');
      const d = await r.json();
      toast.success(`Versão ${d.de} agora é a vigente (gravada como v${d.nova_versao}).`);
    } catch (e: any) {
      toast.error(`Não deu para restaurar: ${String(e.message || e)}`);
    }
    setRestaurando(false);
  };

  // ---- Controles de configuração específicos (alternador de abas + opções) ----
  const configExtras = (
    <>
      <div className="config-group" style={{ marginBottom: 10 }}>
        {/* Carregar uma versão do histórico só trocava o que aparece na tela: o conteúdo vigente
            continuava sendo o da última alteração, e o refino seguinte partia dele. Este botão
            torna vigente a versão carregada — é como se volta de um refino que estragou. */}
        <button
          className="btn-requirements-compact"
          disabled={!currentSessionId || !currentLoadedVersion || restaurando}
          onClick={handleRestaurar}
          title="Torna vigente a versão carregada do histórico (o refino seguinte parte dela)"
        >
          {restaurando ? '⏳ Restaurando…' : `♻️ Tornar vigente${currentLoadedVersion ? ` (v${currentLoadedVersion})` : ''}`}
        </button>
        <button
          className="btn-requirements-compact"
          disabled={!currentSessionId || estruturando}
          onClick={handleEstruturar}
          title="Converte a prosa de cada tarefa num contrato de passos com tipos fechados, validado antes de gravar"
        >
          {estruturando ? '⏳ Estruturando passos…' : '🧩 Estruturar passos'}
        </button>
        {relatorioPassos && (
          <div style={{ marginTop: 8, fontSize: 12, lineHeight: 1.5 }}>
            {relatorioPassos.map((r, i) => (
              <div key={i} style={{ padding: '4px 0', borderBottom: '1px solid #eee' }}>
                <b>{r.tarefa}</b> — {r.situacao}
                {typeof r.passos === 'number' ? ` · ${r.passos} passos` : ''}
                {r.invalidos ? ` · ${r.invalidos} sem validar` : ''}
                {r.erro ? ` · ${String(r.erro).slice(0, 80)}` : ''}
                {r.erro_agente ? ` · agente: ${String(r.erro_agente).slice(0, 80)}` : ''}
                {Array.isArray(r.reparos) && r.reparos.length > 0 && (
                  <div style={{ color: '#166534', paddingLeft: 12 }}>
                    {r.reparos.map((x: string, k: number) => <div key={k}>✓ {x}</div>)}
                  </div>
                )}
                {Array.isArray(r.problemas) && r.problemas.length > 0 && (
                  <div style={{ color: '#9a3412', paddingLeft: 12 }}>
                    {r.problemas.map((x: any, k: number) => <div key={k}>✗ passo {x.passo}: {x.motivo}</div>)}
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </div>
      {tabSwitcher}

      <label>Nível de Detalhamento</label>
      <select
        value={detailLevel}
        onChange={(e) => setDetailLevel(e.target.value as any)}
        style={{
          width: '100%',
          padding: '10px',
          border: '1px solid #e5e7eb',
          borderRadius: '6px',
          fontSize: '13px',
          marginBottom: '12px'
        }}
      >
        <option value="concise">Conciso</option>
        <option value="balanced">Balanceado</option>
        <option value="detailed">Detalhado</option>
      </select>

      <label>Frameworks Suportados</label>
      <div style={{ marginBottom: '12px' }}>
        {['CrewAI', 'AutoGen', 'LangChain', 'Custom'].map(fw => (
          <label key={fw} className="checkbox-label">
            <input
              type="checkbox"
              checked={selectedFrameworks.includes(fw)}
              onChange={(e) => {
                if (e.target.checked) {
                  setSelectedFrameworks([...selectedFrameworks, fw]);
                } else {
                  setSelectedFrameworks(selectedFrameworks.filter(f => f !== fw));
                }
              }}
            />
            <span>{fw}</span>
          </label>
        ))}
      </div>
    </>
  );

  // ---- Chat de refino (coluna do meio) ----
  const chatPanel = (
    <>
      {isChatProcessing && (
        <div className="generating-indicator">
          <div className="indicator-content">
            <span className="spinner">⏳</span>
            <strong>🚀 GERANDO TASKS.YAML...</strong>
            <span className="blink">Aguarde, isso pode levar 1-2 minutos</span>
          </div>
        </div>
      )}

      <ChatInterface
        messages={chatMessages}
        onSendMessage={handleChatSend}
        isProcessing={isChatProcessing}
      />
    </>
  );

  // ---- Miolo (coluna principal): visualizador do tasks.yaml ----
  const yamlViewer = generatedYaml ? (
    <DocumentActionsCard
      filename={yamlFilename}
      content={generatedYaml}
      executionId={currentSessionId}
      projectId={projectId}
      hasDiff={showDiff && !!oldYaml}
      version={currentLoadedVersion}
      onViewDiff={() => setIsDiffModalOpen(true)}
      onEdit={() => setIsEditorOpen(true)}
      onView={() => setIsViewerOpen(true)}
      onExportPDF={async () => {
        const { exportMarkdownToPDF } = await import('../../services/pdfExportService');
        await exportMarkdownToPDF(generatedYaml, yamlFilename.replace('.yaml', '.pdf'));
      }}
    />
  ) : (
    <div className="no-document-placeholder">
      <div className="placeholder-icon">📋</div>
      <h3>Nenhum tasks.yaml Gerado</h3>
      <p>Selecione um documento MD de especificação e clique em "Gerar tasks.yaml"</p>
    </div>
  );

  return (
    <StagePageLayout
      title="📦 YAML de Agentes e Tarefas"
      subtitle="Gere agents.yaml e tasks.yaml a partir de documentos de especificação"
      sidebarTitle="📋 Configuração"
      wideViewer
      sourceButtons={sourceButtons}
      sourceBanner={sourceBanner}
      configExtras={configExtras}
      instructions={customInstructions}
      onInstructionsChange={setCustomInstructions}
      onGenerate={startGeneration}
      generating={isGenerating}
      generateLabel="🚀 Gerar tasks.yaml"
      canGenerate={!!selectedSpecSessionId}
      onReview={handleReview}
      reviewing={isReviewing}
      canReview={!!generatedYaml}
      onHistory={() => setIsHistoryModalOpen(true)}
      chat={chatPanel}
      modals={
        <>
          {/* Modal for Agent/Task Spec Document Selection */}
          <AgentTaskSpecHistoryModal
            isOpen={isSpecModalOpen}
            onClose={() => setIsSpecModalOpen(false)}
            projectId={projectId || ''}
            onSelectSession={handleSpecSessionSelect}
            onSelectVersion={handleSpecVersionSelect}
          />

          {/* Modal for tasks.yaml History */}
          <TasksYamlHistoryModal
            isOpen={isHistoryModalOpen}
            onClose={() => setIsHistoryModalOpen(false)}
            projectId={projectId || ''}
            onSelectSession={handleHistorySessionSelect}
            onSelectVersion={handleHistoryVersionSelect}
          />

          {/* YAML Viewer Modal */}
          <YamlViewerModal
            isOpen={isViewerOpen}
            content={generatedYaml}
            filename={yamlFilename}
            onClose={() => setIsViewerOpen(false)}
          />

          {/* Markdown Editor Modal */}
          <MarkdownEditorModal
            isOpen={isEditorOpen}
            content={generatedYaml}
            filename={yamlFilename}
            onSave={handleSaveEdit}
            onClose={() => setIsEditorOpen(false)}
          />

          {/* Diff Viewer Modal */}
          <DiffViewerModal
            isOpen={isDiffModalOpen}
            oldDocument={oldYaml}
            newDocument={generatedYaml}
            onClose={() => setIsDiffModalOpen(false)}
          />

          {/* Review Suggestions Modal */}
          <ReviewSuggestionsModal
            isOpen={isReviewModalOpen}
            suggestions={reviewSuggestions}
            onClose={() => setIsReviewModalOpen(false)}
            onApply={handleApplySuggestions}
            isApplying={isApplyingSuggestions}
          />
        </>
      }
    >
      {yamlViewer}
    </StagePageLayout>
  );
};

export default TasksYamlTab;
